-- ====================================================================
-- zendesk_colonias.sql  ·  Traducción ULID -> nombre (colonias/delegaciones)
-- Generado desde colonias-delegaciones.csv (1355 colonias, 7 delegaciones)
-- Idempotente: se puede re-ejecutar. Usa la BD portal_qro.
-- ====================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS zendesk_colonias (
  colonia_ulid      CHAR(26)     NOT NULL,
  nombre            VARCHAR(200) NOT NULL,
  colonia_key       INT          NULL,
  delegacion_ulid   CHAR(26)     NULL,
  delegacion_nombre VARCHAR(120) NULL,
  delegacion_capa   VARCHAR(120) NULL,
  estado            TINYINT      NOT NULL DEFAULT 1,
  PRIMARY KEY (colonia_ulid),
  KEY idx_deleg_ulid (delegacion_ulid),
  KEY idx_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS zendesk_delegaciones (
  delegacion_ulid CHAR(26)     NOT NULL,
  nombre          VARCHAR(120) NOT NULL,
  PRIMARY KEY (delegacion_ulid),
  KEY idx_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Recarga limpia del catálogo
TRUNCATE TABLE zendesk_colonias;
TRUNCATE TABLE zendesk_delegaciones;









-- ====================================================================
-- BACKFILL · corrige los tickets ya cargados (idempotente)
-- ====================================================================

-- 1) Asegura que cat_delegacion tenga los 7 nombres canónicos
SELECT nombre FROM zendesk_delegaciones;

-- 2) Repunta delegacion_id: filas cuyo "nombre" es un ULID -> nombre real
UPDATE tickets t
  JOIN cat_delegacion       old  ON old.id = t.delegacion_id
  JOIN zendesk_delegaciones zd   ON zd.delegacion_ulid = old.nombre
  JOIN cat_delegacion       good ON good.nombre = zd.nombre
  SET t.delegacion_id = good.id
  WHERE old.nombre <> good.nombre;

-- 3) Fallback: deriva la delegación desde la colonia del ticket
--    (mientras t.colonia todavía guarda el ULID de la colonia)
UPDATE tickets t
  JOIN zendesk_colonias zc   ON zc.colonia_ulid = t.colonia
  JOIN cat_delegacion   good ON good.nombre = zc.delegacion_nombre
  SET t.delegacion_id = good.id
  WHERE t.delegacion_id IS NULL
     OR t.delegacion_id IN (SELECT id FROM (SELECT id FROM cat_delegacion WHERE nombre RLIKE '^[0-9A-Z]{26}$') x);

-- 4) Traduce la colonia: ULID -> nombre legible
UPDATE tickets t
  JOIN zendesk_colonias zc ON zc.colonia_ulid = t.colonia
  SET t.colonia = zc.nombre;

-- 5) Limpia las filas basura (ULID) de cat_delegacion ya sin tickets
DELETE c FROM cat_delegacion c
  LEFT JOIN tickets t ON t.delegacion_id = c.id
  WHERE c.nombre RLIKE '^[0-9A-Z]{26}$' AND t.ticket_id IS NULL;

